{"cards": [{"node_code": "N_82882987e65c84f2", "definition": "研究机务段内部机车运用计划的编制、机车乘务员的排班与调配、机车出入段作业组织及调度指挥流程的管理技术与方法。", "boundary": "本节点聚焦于机务段层面的微观调度与作业组织。边界在于区分“机务段调度”与“列车调度”（后者侧重全线列车运行图执行，归入铁路运输组织）；区分“调度”与“检修”（调度侧重运用计划，检修侧重设备状态）。若涉及跨段机车调配，主挂载视管理主体而定，段内作业归本节点。", "includes": ["机务段机车运用计划编制与调整", "机车乘务员排班、轮乘及劳动组织", "机车出入段、整备作业流程的调度指挥"], "excludes": ["铁路全线列车运行图编制与列车调度指挥", "机车定期检修计划与故障维修调度"], "sibling_distinctions": [{"other_code": "N_391778b34bc14059", "rule": "区分依据为功能层级：本节点侧重具体的作业计划与实时调度指挥；兄弟节点侧重宏观的管理制度、统计分析及自动化系统建设。"}, {"other_code": "N_118a4811a4da18d5", "rule": "区分依据为对象状态：本节点侧重机车在运用流转中的调度安排；兄弟节点侧重机车在整备场内的具体技术整备作业。"}], "cross_boundary_rule": "若内容涉及“调度系统”的技术实现，若侧重业务流程与规则归本节点；若侧重软件架构或硬件设备归管理自动化。"}, {"node_code": "N_391778b34bc14059", "definition": "研究机车运用管理的制度体系、统计分析方法、绩效考核机制，以及支撑机车运用管理的信息系统、自动化技术与智能化应用。", "boundary": "本节点聚焦于机车运用的“管理”维度与“技术支撑”维度。边界在于区分“管理”与“调度”（调度是管理的具体执行环节，归入机务段机车调度）；区分“自动化”与“操纵”（操纵是司机操作，自动化是系统辅助）。若涉及具体调度指令，归调度；若涉及管理指标体系或系统平台，归本节点。", "includes": ["机车运用管理制度、统计分析与效率评估", "机车运用管理信息系统（MIS）及自动化平台", "机车运用数据的采集、处理与智能决策支持"], "excludes": ["具体的机车调度指令下达与乘务员排班操作", "机车司机驾驶操作技术与规程"], "sibling_distinctions": [{"other_code": "N_82882987e65c84f2", "rule": "区分依据为抽象层级：本节点侧重管理理论、制度设计与系统工具；兄弟节点侧重具体的作业计划编制与实时调度执行。"}, {"other_code": "N_618e0bd0cb04a01f", "rule": "区分依据为研究目标：本节点侧重管理效率与系统支撑；兄弟节点侧重设备在运用过程中的可靠性指标与故障分析。"}], "cross_boundary_rule": "若内容涉及“基于大数据的调度优化”，若侧重算法模型与系统实现归本节点；若侧重调度规则本身归机务段机车调度。"}, {"node_code": "N_618e0bd0cb04a01f", "definition": "研究机车在运用过程中的可靠性理论、故障模式分析、寿命预测及基于运用数据的可靠性评估与维护策略优化。", "boundary": "本节点聚焦于机车在“运用”状态下的可靠性表现。边界在于区分“运用可靠性”与“检修”（检修侧重修复与保养，归入机务段、机车保养与检修）；区分“可靠性”与“设计”（设计侧重固有可靠性，归入机车设计与计算）。若涉及故障后的维修作业，归检修；若涉及运用中的故障率统计与预测，归本节点。", "includes": ["机车运用可靠性指标体系与评估方法", "机车故障模式、影响及危害性分析（FMEA）", "基于运用数据的寿命预测与预防性维护策略"], "excludes": ["机车结构强度设计与固有可靠性设计", "机车定期检修工艺、大修流程及故障修复作业"], "sibling_distinctions": [{"other_code": "N_391778b34bc14059", "rule": "区分依据为侧重点：本节点侧重设备本身的可靠性特性与故障规律；兄弟节点侧重管理流程与系统工具。"}, {"other_code": "N_4345e98b3364f6bb", "rule": "区分依据为阶段：本节点侧重运用过程中的可靠性监测与预测；兄弟节点侧重停机后的检修执行与保养规程。"}], "cross_boundary_rule": "若内容涉及“可靠性维修策略”，若侧重策略制定与数据分析归本节点；若侧重具体维修作业实施归机务段、机车保养与检修。"}]}
